window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e6b3969b4bb35787"]={"versions": [{"id": "FIG-e6b3969b4bb35787", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM/UML-basiertes Prozessdiagramm) für die Adaptive Platform (AP). Dargestellt ist die übergeordnete Entwurfsaktivität <code>Develop a Service Interface Description</code> im Rahmen der serviceorientierten Systemarchitektur-Definition (SOA), eingebettet in den Datenfluss von Standarddefinitionen hin zu formalen Schnittstellen- und Mapping-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Composite Activity):</strong>\n<ul class=\"fig-list\"><li><code>Develop a Service Interface Description</code> (zentraler Prozessbaustein).\n</li></ul>\n</li><li><strong>Verschachtelte Teilaktivitäten (<code>«nesting»</code> per Komposition/Rhombus):</strong>\n<ul class=\"fig-list\"><li><code>Provide Data Types for Adaptive Platform</code>\n</li><li><code>Define Service Interfaces</code>\n</li><li><code>Aggregate Service Interfaces</code>\n</li></ul>\n</li><li><strong>Eingangs-Artefakt (<code>«input»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> (Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakte (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Service Interface Description</code> (Kardinalität <code>1..*</code>).\n</li><li><code>Service Interface Mapping</code> (Kardinalität <code>0..*</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Optionaler Eingang (<code>0..1</code>) des <code>Autosar AP Standard Package</code> in die zusammengesetzte Aktivität <code>Develop a Service Interface Description</code>.\n</li><li>Interne Strukturierung/Ausführung über drei geschachtelte Teilaktivitäten:\n<ul class=\"fig-list\"><li>Festlegung bzw. Bereitstellung plattformspezifischer Datentypen (<code>Provide Data Types for Adaptive Platform</code>).\n</li><li>Definition der Service-Schnittstellen (<code>Define Service Interfaces</code>).\n</li><li>Aggregation der Schnittstellenelemente (<code>Aggregate Service Interfaces</code>).\n</li></ul>\n</li><li>Erzeugung der Ausgangsergebnisse:\n<ul class=\"fig-list\"><li>Mindestens eine oder mehrere Schnittstellenbeschreibungen (<code>Service Interface Description</code>, <code>1..*</code>).\n</li><li>Optionale Mappings der Schnittstellen (<code>Service Interface Mapping</code>, <code>0..*</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstellenbeschreibungen bilden das verbindliche formale Vertragsmodell für Service-Provider und Service-Consumer auf der AUTOSAR Adaptive Platform. Die Spezifikation verlangt mindestens eine <code>Service Interface Description</code> (<code>1..*</code>), während Schnittstellen-Mappings (<code>0..*</code>) und die Verwendung des Standard-Pakets (<code>0..1</code>) optional sind. Alle Datentypen und Services müssen konsistent modelliert und aggregiert werden, um downstream die Codegenerierung (Proxies/Skeletons) und die Kommunikationskonfiguration zu ermöglichen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-71db34f17d14ab9d", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM/UML-basiertes Prozessdiagramm) für die Adaptive Platform (AP). Dargestellt ist die übergeordnete Entwurfsaktivität <code>Develop a Service Interface Description</code> im Rahmen der serviceorientierten Systemarchitektur-Definition (SOA), eingebettet in den Datenfluss von Standarddefinitionen hin zu formalen Schnittstellen- und Mapping-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteur &amp; Rolle:</strong>\n<ul class=\"fig-list\"><li><code>OEM</code> in der Rolle <code>+Service Interface Designer</code>, zugeordnet über <code>«performs»</code>.\n</li></ul>\n</li><li><strong>Aktivität (Composite Activity):</strong>\n<ul class=\"fig-list\"><li><code>Develop a Service Interface Description</code> (zentraler Prozessbaustein).\n</li></ul>\n</li><li><strong>Verschachtelte Teilaktivitäten (<code>«nesting»</code> per Komposition/Rhombus):</strong>\n<ul class=\"fig-list\"><li><code>Select or define Data Types for Adaptive Platform</code>\n</li><li><code>Define Service Interfaces</code>\n</li><li><code>Aggregate Service Interfaces</code> (Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><strong>Eingangs-Artefakt (<code>«input»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> (Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakte (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Service Interface Description</code> (Kardinalität <code>1..*</code>).\n</li><li><code>Service Interface Mapping</code> (Kardinalität <code>0..*</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>OEM</code> führt in der Rolle des <code>+Service Interface Designer</code> (<code>«performs»</code>) die Aktivität <code>Develop a Service Interface Description</code> aus.\n</li><li>Optionaler Eingang (<code>0..1</code>) des <code>Autosar AP Standard Package</code>.\n</li><li>Ausführung der verschachtelten Methodikschritte:\n<ul class=\"fig-list\"><li>Auswahl oder Definition der Datentypen (<code>Select or define Data Types for Adaptive Platform</code>).\n</li><li>Definition der Service Interfaces (<code>Define Service Interfaces</code>).\n</li><li>Optionale Aggregation von Service Interfaces (<code>Aggregate Service Interfaces</code>, Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li>Erzeugung der Modellartefakte:\n<ul class=\"fig-list\"><li>Mindestens eine Service-Schnittstellenbeschreibung (<code>Service Interface Description</code>, <code>1..*</code>).\n</li><li>Optionale Mappings (<code>Service Interface Mapping</code>, <code>0..*</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Verantwortung für die Erstellung der Service-Schnittstellenbeschreibungen ist explizit dem <code>OEM</code> in der Rolle <code>Service Interface Designer</code> zugeordnet. Die Teilaktivität <code>Aggregate Service Interfaces</code> ist durch die Multiplizität <code>0..1</code> als optional gekennzeichnet. Die Aktivitäten erlauben neben der Neudefinition auch die Wiederverwendung bestehender Datentypen (<code>Select or define Data Types for Adaptive Platform</code>). Die resultierenden Schnittstellendefinitionen (<code>1..*</code>) sind Voraussetzung für die konsistente Software-Architektur und Schnittstellenimplementierung im Gesamtsystem.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5168d75e74fc5f81", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM/UML-basiertes Prozessdiagramm) für die Adaptive Platform (AP). Dargestellt ist die übergeordnete Entwurfsaktivität <code>Develop a Service Interface Description</code> im Rahmen der serviceorientierten Systemarchitektur-Definition (SOA), eingebettet in den Datenfluss von Standarddefinitionen hin zu formalen Schnittstellen- und Mapping-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteur &amp; Rolle:</strong>\n<ul class=\"fig-list\"><li><code>OEM</code> in der Rolle <code>+Service Interface Designer</code>, zugeordnet über <code>«performs»</code>.\n</li></ul>\n</li><li><strong>Aktivität (Composite Activity):</strong>\n<ul class=\"fig-list\"><li><code>Develop a Service Interface Description</code> (zentraler Prozessbaustein).\n</li></ul>\n</li><li><strong>Verschachtelte Teilaktivitäten (<code>«nesting»</code> per Komposition/Rhombus):</strong>\n<ul class=\"fig-list\"><li><code>Select or define Data Types for Adaptive Platform</code>\n</li><li><code>Define Service Interfaces</code>\n</li><li><code>Aggregate Service Interfaces</code> (Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><strong>Eingangs-Artefakt (<code>«input»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> (Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakte (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Service Interface Description</code> (Kardinalität <code>1..*</code>).\n</li><li><code>Service Interface Mapping</code> (Kardinalität <code>0..*</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>OEM</code> führt in der Rolle des <code>+Service Interface Designer</code> (<code>«performs»</code>) die Aktivität <code>Develop a Service Interface Description</code> aus.\n</li><li>Optionaler Eingang (<code>0..1</code>) des <code>Autosar AP Standard Package</code>.\n</li><li>Ausführung der verschachtelten Methodikschritte:\n<ul class=\"fig-list\"><li>Auswahl oder Definition der Datentypen (<code>Select or define Data Types for Adaptive Platform</code>).\n</li><li>Definition der Service Interfaces (<code>Define Service Interfaces</code>).\n</li><li>Optionale Aggregation von Service Interfaces (<code>Aggregate Service Interfaces</code>, Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li>Erzeugung der Modellartefakte:\n<ul class=\"fig-list\"><li>Mindestens eine Service-Schnittstellenbeschreibung (<code>Service Interface Description</code>, <code>1..*</code>).\n</li><li>Optionale Mappings (<code>Service Interface Mapping</code>, <code>0..*</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Verantwortung für die Erstellung der Service-Schnittstellenbeschreibungen ist explizit dem <code>OEM</code> in der Rolle <code>Service Interface Designer</code> zugeordnet. Die Teilaktivität <code>Aggregate Service Interfaces</code> ist durch die Multiplizität <code>0..1</code> als optional gekennzeichnet. Die Aktivitäten erlauben neben der Neudefinition auch die Wiederverwendung bestehender Datentypen (<code>Select or define Data Types for Adaptive Platform</code>). Die resultierenden Schnittstellendefinitionen (<code>1..*</code>) sind Voraussetzung für die konsistente Software-Architektur und Schnittstellenimplementierung im Gesamtsystem.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e6b3969b4bb35787", "to": "FIG-71db34f17d14ab9d", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Akteurs-Rolle: Organisation <code>OEM</code> führt über die Beziehung <code>«performs»</code> als <code>+Service Interface Designer</code> die Aktivität <code>Develop a Service Interface Description</code> aus.\n</li><li>Umbenennung des Teilaktivitäts-Schritts von <code>Provide Data Types for Adaptive Platform</code> zu <code>Select or define Data Types for Adaptive Platform</code>.\n</li><li>Ergänzung der Kardinalität <code>0..1</code> an der Kompositionsbeziehung (<code>«nesting»</code>) zu <code>Aggregate Service Interfaces</code>.\n</li></ul>"}, {"from": "FIG-71db34f17d14ab9d", "to": "FIG-5168d75e74fc5f81", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
